        H(i,i) = 3750;
        H(i,i+1) = -2500;
        H(i,i+2) = 625;
    elseif i == n-1
        H(i,i-2) = 625;
        H(i,i-1) = -2500;
        H(i,i) = 3750;
        H(i,i+1) = -2500;
    elseif i == n
        H(i,i-2) = 625;
        H(i,i-1) = -2500;
